async function readCloud(){const res=await gh(`/contents/${CLOUD_FILE}`);if(res.status===404)return null;if(!res.ok)throw new CloudError(res.status);const j=await res.json(),text=j.content?fromB64(j.content):await(await gh(`/contents/${CLOUD_FILE}`,{headers:{Accept:"application/vnd.github.raw+json"}})).text();return{sha:j.sha,data:JSON.parse(text)};}
function cloudSay(text,bad){$("cloudStatus").textContent=text;$("cloudStatus").classList.toggle("cloudbad",!!bad);}
